import { Component, DestroyRef, inject, OnInit, signal } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { catchError, map, throwError } from 'rxjs';
import { Lugar } from '../lugar.model';
import { LugaresComponent } from '../lugares.component';

@Component({
  selector: 'app-lugares-disponibles',
  imports: [LugaresComponent],
  templateUrl: './lugares-disponibles.component.html',
})
export class LugaresDisponiblesComponent implements OnInit {
  private httpClient = inject(HttpClient);
  private destroyRef = inject(DestroyRef);
  lugares = signal<Lugar[] | undefined>(undefined);
  estaRecibiendo = signal(false);
  error = signal('');

  ngOnInit() {
    this.estaRecibiendo.set(true);
    const suscripcion = this.httpClient
      .get<{ lugares: Lugar[] }>('http://localhost:3000/lugares')
      .pipe(
        map((datosRespuesta) => datosRespuesta.lugares),
        catchError((error) => {
          console.log(error.message);
          return throwError(
            () =>
              new Error(
                'Algo salió mal al obtener los lugares disponibles. Por favor, intenta nuevamente más tarde.',
              ),
          );
        }),
      )
      .subscribe({
        next: (lugares) => this.lugares.set(lugares),
        complete: () => this.estaRecibiendo.set(false),
        error: (error: Error) => this.error.set(error.message),
      });
    this.destroyRef.onDestroy(() => suscripcion.unsubscribe());
  }
}
